export default function P2() {
/*
    已知有数组 const colors = ['red', 'green', 'blue']
    请根据数组中的元素创建三个不同的 div 元素，每个 div 元素的背景颜色为数组中的元素
*/  
const colors = ['red', 'green', 'blue']
const divs = colors.map((color) => (
    <div>
        {color}
    </div>
))
return (
    <div>
        {divs}
    </div>
)
}
